<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3 mb-1">Histórico de treinos</h1><p class="text-secondary mb-0">Sessões, aderência, séries e volume realizado.</p></div><a class="btn btn-outline-secondary" href="<?= escapar(url('/treinos')) ?>">Treinos de hoje</a></div>
<div class="card"><?php if (!$registros): ?><div class="card-body p-5 text-center"><i class="bi bi-clock-history display-5 text-success"></i><h2 class="h5 mt-3">Nenhum treino registrado</h2><p class="text-secondary">As sessões aparecerão aqui após o primeiro registro.</p></div><?php else: ?><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Data</th><th>Treino</th><th>Situação</th><th>Exercícios</th><th>Séries</th><th>Aderência</th><th>Volume</th><th class="tabela-acoes"></th></tr></thead><tbody><?php foreach ($registros as $registro): ?><?php $situacao = SITUACOES_TREINO[$registro['trr_situacao']] ?? ['rotulo' => $registro['trr_situacao'], 'classe' => 'text-bg-secondary']; ?><tr><td class="fw-semibold"><?= escapar(formatar_data($registro['trr_data'])) ?></td><td><?= escapar($registro['trr_treino_nome']) ?></td><td><span class="badge <?= escapar($situacao['classe']) ?>"><?= escapar($situacao['rotulo']) ?></span></td><td><?= (int) $registro['total_exercicios'] ?></td><td><?= (int) $registro['total_series'] ?></td><td><?= $registro['resumo']['aderencia'] === null ? '—' : $registro['resumo']['aderencia'] . '%' ?></td><td><?= formatar_decimal($registro['resumo']['volume']) ?> kg</td><td><a class="btn btn-sm btn-outline-success btn-icone" href="<?= escapar(url('/treinos/realizados/detalhes?id=' . $registro['trr_id'])) ?>"><i class="bi bi-eye"></i></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
